mapper.select:
select a.id, a.project_id AS projectId, a.monomer_id AS monomerId, a.area_id AS areaId, a.project_type AS projectType, a.product_type AS productType, a.category, a.measure_mode AS measureMode, CASE WHEN a.product_type = 32 THEN a.purchase_details_id ELSE a.product_id END AS 'product_id', a.serial_number AS serialNumber, a.name, a.specification, a.material, a.length, a.width, a.thickness, a.quantity, a.net_weight AS netWeight, a.weight, a.mete, a.total_area AS totalArea, a.measure_unit AS measureUnit, a.accounting_unit AS accountingUnit, a.area_type AS areaType, a.source_id AS sourceId, a.source_type AS sourceType, a.supplier_id AS supplierId, a.supplier_name AS supplierName, a.bool_problem_receiving AS boolProblemReceiving, a.problem_desc AS problemDesc, a.problem_id AS problemId, a.purchase_details_id AS purchaseDetailsId, a.operate_record_id AS operateRecordId, a.classify_id AS classifyId, a.actual_received_mete AS actualReceivedMete, a.link_id AS linkId, a.reject_quantity AS rejectQuantity, a.reject_mete as rejectMete, a.reject_actual_received_mete as rejectActualReceivedMete, a.create_time as createTime, a.purchase_details_id as purchaseDetailsId, b.user_name as userName, b.serial_number as purchaseSn, ap.id as 'enclosurePlanId', spod.wage_quota_type as wageQuotaType, ss.id as 'supplier.id', ss.name as 'supplier.name', pm.id as 'monomer.id', pm.name as 'monomer.name', pa.id as 'area.id', pa.name as 'area.name', ap.id as 'batch.id', ap.name as 'batch.name' FROM project_receiving_record as a left join project_purchase_order_received_operate_record as b on a.operate_record_id = b.id left join scm_purchase_order_detail as spod on a.purchase_details_id = spod.id left join scm_supplier as ss on b.supplier_id = ss.id left join plan_monomer as pm on a.monomer_id = pm.id left join plan_area as pa on a.area_id = pa.id left join tech_enclosure as te on a.product_id = te.id left join enclosure_plan as ap on te.enclosure_plan_id = ap.id where a.bool_delete_enum = 0 and a.source_type = 2 and a.project_id = #{projectId}
and a.product_type = #{productType}
and a.monomer_id = #{monomerId}
and a.area_id = #{areaId}
and (pm.name like concat('%',#{monomerOrArea},'%') or pa.name like concat('%',#{monomerOrArea},'%') or ap.name like concat('%',#{monomerOrArea},'%'))
and b.supplier_id = #{supplierId}
and b.serial_number like concat('%',#{purchaseSn},'%')
and b.user_name like concat('%',#{userName},'%')
and a.name like concat('%',#{name},'%')
and a.specification like concat('%',#{specification},'%')
and a.serial_number like concat('%',#{serialNumber},'%')
and DATE_FORMAT(a.create_time,'%Y-%m-%d') >= DATE_FORMAT(#{receivedTime[0]},'%Y-%m-%d')
and DATE_FORMAT(a.create_time,'%Y-%m-%d') <= DATE_FORMAT(#{receivedTime[1]},'%Y-%m-%d')
order by a.id desc

select prr.id, prr.purchase_details_id purchaseDetailId, spo.id purchaseId, "3" type, prr.create_time createTime from project_receiving_record prr left join scm_purchase_order_detail spod on spod.id = prr.purchase_details_id and spod.bool_delete_enum = 0 left join project_purchase_order_received_operate_record as pporor on pporor.id = prr.operate_record_id INNER JOIN scm_purchase_order spo ON spod.purchase_id = spo.id AND spo.bool_delete_enum = 0 AND spo.data_status = 2 where prr.bool_delete_enum = 0 and prr.source_type = 2
and spod.basic_class & #{query.basicClassBit} > 0
and spod.basic_class = #{query.basicClass}
and pporor.user_name like CONCAT('%', #{query.createUser},'%')
and prr.name like CONCAT('%', #{query.className},'%')
and prr.create_time >= #{query.startTime}
and prr.create_time <= #{query.endTime}
and prr.project_id = #{query.projectId}
and spo.serial_number like CONCAT('%', #{query.purchaseSerialNumber},'%')
and spo.supplier_id = #{query.supplierId}
and prr.specification like CONCAT('%', #{query.specification},'%')
and spo.branch_company_id = #{query.branchCompanyId}
